<?php $this->assign('title', $solicitacao->numero); ?><div class="d-flex justify-content-between mb-4"><div><h1 class="h3"><?= h($solicitacao->numero) ?></h1><span class="badge text-bg-secondary"><?= h(str_replace('_', ' ', $solicitacao->status)) ?></span></div><div class="d-flex gap-2"><?php if (in_array($solicitacao->status, ['solicitada', 'em_cotacao'], true)): ?><?= $this->Html->link('Adicionar cotação', ['action' => 'cotar', $solicitacao->id], ['class' => 'btn btn-outline-primary']) ?><?php endif; ?><?php if ($solicitacao->status === 'aguardando_aprovacao'): ?><?= $this->Form->postLink('Aprovar', ['action' => 'decidir', $solicitacao->id], ['data' => ['decisao' => 'aprovar'], 'class' => 'btn btn-success']) ?> <?= $this->Form->postLink('Rejeitar', ['action' => 'decidir', $solicitacao->id], ['data' => ['decisao' => 'rejeitar', 'motivo' => 'Rejeitado pelo aprovador'], 'class' => 'btn btn-danger']) ?><?php endif; ?><?php if ($solicitacao->status === 'aprovada'): ?><?= $this->Form->postLink('Emitir pedido', ['action' => 'emitir', $solicitacao->id], ['class' => 'btn btn-primary']) ?><?php endif; ?></div></div><div class="card border-0 shadow-sm mb-3"><div class="card-body"><strong>Justificativa:</strong> <?= nl2br(h($solicitacao->justificativa)) ?></div><table class="table mb-0"><thead><tr><th>Item</th><th>Quantidade</th><th>Estimado</th></tr></thead><tbody><?php foreach ($solicitacao->solicitacoes_compras_itens as $item): ?><tr><td><?= h($item->medicamento?->nome_comercial ?? $item->produto?->nome ?? '-') ?></td><td><?= h($item->quantidade) ?></td><td><?= h($item->preco_estimado) ?></td></tr><?php endforeach; ?></tbody></table></div><h2 class="h5">Cotações</h2><?php foreach ($solicitacao->cotacoes as $cotacao): ?><div class="card mb-2"><div class="card-body d-flex justify-content-between"><span><?= h($cotacao->fornecedor->razao_social ?? '-') ?> · R$ <?= number_format((float)$cotacao->valor_total, 2, ',', '.') ?></span><?php if ($solicitacao->status === 'em_cotacao'): ?><?= $this->Form->postLink('Selecionar', ['action' => 'selecionar', $solicitacao->id, $cotacao->id], ['class' => 'btn btn-sm btn-primary']) ?><?php endif; ?></div></div><?php endforeach; ?>
